            assert_eq!(
                Some(q),
                select(&s, &pool, Some([6.0, 3.0, 1.0]), &seed).unwrap()
            );
            counts[if q == 10 {
                0
            } else if q == 11 {
                1
            } else {
                2
            }] += 1;

